import{_ as o,r,o as l,c as i,b as a,d as n,a as s,w as d,e as c}from"./app-84ed3530.js";const p={};function u(h,t){const e=r("RouterLink");return l(),i("div",null,[t[13]||(t[13]=a("h1",{id:"mysql-核心知识体系",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#mysql-核心知识体系","aria-hidden":"true"},"#"),n(" MySQL 核心知识体系")],-1)),a("blockquote",null,[a("p",null,[t[1]||(t[1]=n("面向全栈工程师的 MySQL 深度整理：架构、事务与 MVCC、索引、锁、日志链路、性能优化、高可用与扩展。默认讨论 ",-1)),t[2]||(t[2]=a("strong",null,"InnoDB 引擎 + MySQL 8.0/8.4 LTS",-1)),t[3]||(t[3]=n("（PostgreSQL 对照见 ",-1)),s(e,{to:"/blogs/backend/PostgreSQL.html"},{default:d(()=>[...t[0]||(t[0]=[n("PostgreSQL 笔记",-1)])]),_:1}),t[4]||(t[4]=n("）。",-1))])]),t[14]||(t[14]=c(`<hr><h2 id="_1-整体架构" tabindex="-1"><a class="header-anchor" href="#_1-整体架构" aria-hidden="true">#</a> 1. 整体架构</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> TB
  <span class="token keyword">subgraph</span> Server<span class="token text string">[&quot;Server 层（跨引擎）&quot;]</span>
    C<span class="token text string">[&quot;连接器&lt;br/&gt;认证/连接池&quot;]</span> <span class="token arrow operator">--&gt;</span> A<span class="token text string">[&quot;分析器&lt;br/&gt;词法/语法&quot;]</span>
    A <span class="token arrow operator">--&gt;</span> O<span class="token text string">[&quot;优化器&lt;br/&gt;选索引/JOIN 顺序&quot;]</span>
    O <span class="token arrow operator">--&gt;</span> E<span class="token text string">[&quot;执行器&lt;br/&gt;调引擎接口&quot;]</span>
    E <span class="token arrow operator">--&gt;</span> L<span class="token text string">[&quot;binlog（Server 层日志）&quot;]</span>
  <span class="token keyword">end</span>
  <span class="token keyword">subgraph</span> InnoDB<span class="token text string">[&quot;InnoDB 引擎层&quot;]</span>
    B<span class="token text string">[&quot;Buffer Pool&lt;br/&gt;数据/索引页缓存&quot;]</span> <span class="token arrow operator">---</span> R<span class="token text string">[&quot;redo log / undo log&quot;]</span>
    B <span class="token arrow operator">---</span> T<span class="token text string">[&quot;事务与锁（MVCC）&quot;]</span>
  <span class="token keyword">end</span>
  E <span class="token arrow operator">--&gt;</span> B
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>记忆点：<strong>binlog 在 Server 层（所有引擎共有），redo/undo 在 InnoDB 层</strong>。一个 SQL 的生命线：连接器 → （查缓存已移除）→ 分析器 → 优化器 → 执行器 → 引擎。</p><hr><h2 id="_2-事务-acid、隔离级别与-mvcc" tabindex="-1"><a class="header-anchor" href="#_2-事务-acid、隔离级别与-mvcc" aria-hidden="true">#</a> 2. 事务：ACID、隔离级别与 MVCC</h2><h3 id="_2-1-隔离级别与并发问题" tabindex="-1"><a class="header-anchor" href="#_2-1-隔离级别与并发问题" aria-hidden="true">#</a> 2.1 隔离级别与并发问题</h3><table><thead><tr><th>隔离级别</th><th>脏读</th><th>不可重复读</th><th>幻读</th></tr></thead><tbody><tr><td>READ UNCOMMITTED</td><td>可能</td><td>可能</td><td>可能</td></tr><tr><td>READ COMMITTED（RC）</td><td>避免</td><td>可能</td><td>可能</td></tr><tr><td><strong>REPEATABLE READ（InnoDB 默认）</strong></td><td>避免</td><td>避免</td><td>基本避免*</td></tr><tr><td>SERIALIZABLE</td><td>避免</td><td>避免</td><td>避免</td></tr></tbody></table><p>* InnoDB 在 RR 下通过 <strong>MVCC（快照读）+ Next-Key Lock（当前读）</strong> 把幻读基本堵住了——普通 SELECT 走一致性快照；<code>SELECT ... FOR UPDATE / UPDATE / DELETE</code> 这类当前读靠间隙锁阻止插入。这也是 MySQL 与 PG 的差异点之一（PG 默认 RC）。</p><h3 id="_2-2-mvcc-实现三件套" tabindex="-1"><a class="header-anchor" href="#_2-2-mvcc-实现三件套" aria-hidden="true">#</a> 2.2 MVCC 实现三件套</h3><ol><li><strong>隐藏列</strong>：每行有 <code>trx_id</code>（最后修改事务）与 <code>roll_pointer</code>（指向 undo log 版本链）</li><li><strong>undo log</strong>：旧版本链，回滚 + 多版本读取都靠它</li><li><strong>Read View</strong>：读事务开始时（RC 为每条语句、RR 为第一次快照读）生成「活跃事务列表」，沿版本链找到对自己可见的版本</li></ol><p>一句话：<strong>RC 每条语句取新快照，RR 整个事务用第一次的快照</strong>——这就是两种级别可重复性差异的全部来源。</p><hr><h2 id="_3-索引-面试-80-的题在这" tabindex="-1"><a class="header-anchor" href="#_3-索引-面试-80-的题在这" aria-hidden="true">#</a> 3. 索引（面试 80% 的题在这）</h2><h3 id="_3-1-b-树与两类索引" tabindex="-1"><a class="header-anchor" href="#_3-1-b-树与两类索引" aria-hidden="true">#</a> 3.1 B+ 树与两类索引</h3><ul><li><strong>聚簇索引（主键）</strong>：叶子节点存整行数据，表本身就是按主键组织的 B+ 树</li><li><strong>二级索引（普通/唯一/联合）</strong>：叶子存「索引列 + 主键值」——查到后还要<strong>回表</strong>（拿主键去聚簇索引查整行）</li></ul><p>由此推出两条关键优化：</p><ul><li><strong>覆盖索引</strong>：查询列全在二级索引里，免回表。例：<code>SELECT id, name FROM user WHERE name = ?</code>，在 <code>name</code> 上有索引即可覆盖（name + 主键 id）</li><li><strong>最左前缀</strong>：联合索引 <code>(a, b, c)</code> 相当于建立了 <code>(a)</code>、<code>(a,b)</code>、<code>(a,b,c)</code> 三个前缀；查询必须从最左列开始且连续才能充分利用</li></ul><h3 id="_3-2-索引失效的典型姿势" tabindex="-1"><a class="header-anchor" href="#_3-2-索引失效的典型姿势" aria-hidden="true">#</a> 3.2 索引失效的典型姿势</h3><table><thead><tr><th>写法</th><th>为什么失效</th></tr></thead><tbody><tr><td><code>WHERE YEAR(create_time) = 2026</code></td><td>对列做函数/运算，破坏有序性 → 改成范围查询</td></tr><tr><td><code>WHERE phone = 13800000000</code>（列是 varchar，传了数字）</td><td>隐式类型转换等价于对列加函数</td></tr><tr><td><code>LIKE &#39;%abc&#39;</code></td><td>前缀通配，无法走 B+ 树定位（<code>&#39;abc%&#39;</code> 可以）</td></tr><tr><td><code>WHERE a = 1 OR c = 2</code>（c 无索引）</td><td>OR 一侧全表扫则整体扫</td></tr><tr><td>联合索引 <code>(a,b)</code> 只查 <code>b</code></td><td>违反最左前缀</td></tr></tbody></table><h3 id="_3-3-explain-与慢查询" tabindex="-1"><a class="header-anchor" href="#_3-3-explain-与慢查询" aria-hidden="true">#</a> 3.3 explain 与慢查询</h3><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token keyword">EXPLAIN</span> <span class="token keyword">SELECT</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span> <span class="token punctuation">;</span>
<span class="token comment">-- 关注：type（至少 range，最好 ref/eq_ref/const，ALL=全表扫）</span>
<span class="token comment">--       key（实际用的索引）、rows（扫描行数）、Extra</span>
<span class="token comment">--       Using index = 覆盖索引；Using filesort = 额外排序，优先消除</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>慢查询治理流程：慢日志定位 → explain 归因 → 索引/SQL 改写 → 数据量确认。深分页优化：</p><div class="language-sql line-numbers-mode" data-ext="sql"><pre class="language-sql"><code><span class="token comment">-- 差：OFFSET 1000000, 20 要扫过前 100 万行</span>
<span class="token keyword">SELECT</span> <span class="token operator">*</span> <span class="token keyword">FROM</span> t <span class="token keyword">ORDER</span> <span class="token keyword">BY</span> id <span class="token keyword">LIMIT</span> <span class="token number">1000000</span><span class="token punctuation">,</span> <span class="token number">20</span><span class="token punctuation">;</span>
<span class="token comment">-- 好：游标/键集分页，记录上一页最后的 id</span>
<span class="token keyword">SELECT</span> <span class="token operator">*</span> <span class="token keyword">FROM</span> t <span class="token keyword">WHERE</span> id <span class="token operator">&gt;</span> <span class="token comment">#{last_id} ORDER BY id LIMIT 20;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其他实用结论：<code>count(*)</code> InnoDB 没有缓存行数（MVCC 下「精确总数」因事务而异），大表统计走估算或计数表；JOIN 小表驱动大表，MySQL 8.0.18+ 有 hash join；字符串列尽量用 <code>utf8mb4</code>（8.0 默认），长度够用就好（影响索引大小）。</p><hr><h2 id="_4-锁" tabindex="-1"><a class="header-anchor" href="#_4-锁" aria-hidden="true">#</a> 4. 锁</h2><table><thead><tr><th>锁</th><th>粒度/说明</th></tr></thead><tbody><tr><td>全局锁</td><td><code>FLUSH TABLES WITH READ LOCK</code>，逻辑备份用（或 <code>mysqldump --single-transaction</code> 走一致性快照）</td></tr><tr><td>表锁 / 元数据锁（MDL）</td><td>DDL 会拿 MDL 写锁，长事务未提交会阻塞 DDL 并雪崩后续查询——<strong>DDL 前先查长事务</strong></td></tr><tr><td>行锁（record lock）</td><td>锁的是<strong>索引项</strong>；无索引可用时会升级为锁全表所有记录（RC 下近似表锁效果）</td></tr><tr><td>间隙锁（gap）/ Next-Key</td><td>RR 下当前读锁住区间防幻读；RC 基本没有间隙锁，这是许多公司线上用 RC 的原因</td></tr></tbody></table><p>死锁：InnoDB 自动检测并回滚代价小的事务（<code>SHOW ENGINE INNODB STATUS</code> 可查）。预防：按相同顺序访问资源、小事务、索引到位减少锁范围。</p><hr><h2 id="_5-三大日志与两阶段提交" tabindex="-1"><a class="header-anchor" href="#_5-三大日志与两阶段提交" aria-hidden="true">#</a> 5. 三大日志与两阶段提交</h2><table><thead><tr><th>日志</th><th>层</th><th>作用</th><th>写入时机</th></tr></thead><tbody><tr><td><strong>redo log</strong></td><td>InnoDB</td><td>崩溃恢复（WAL：先写日志再刷数据页），物理日志，循环写</td><td>事务中顺序写 + 后台刷盘</td></tr><tr><td><strong>undo log</strong></td><td>InnoDB</td><td>回滚 + MVCC 版本链，逻辑日志</td><td>事务修改前</td></tr><tr><td><strong>binlog</strong></td><td>Server</td><td>复制 + 时间点恢复（PITR），逻辑日志（推荐 ROW 格式），追加写</td><td>事务提交时</td></tr></tbody></table><p><strong>崩溃不丢数据的保证（两阶段提交）</strong>：更新时先写 redo（prepare）→ 写 binlog → redo（commit）。恢复时以「redo prepare 且 binlog 完整」为准提交，保证主库与从库/恢复点一致。</p><div class="language-ini line-numbers-mode" data-ext="ini"><pre class="language-ini"><code><span class="token comment"># 可靠性关键参数（双 1 配置，金融级）</span>
<span class="token key attr-name">innodb_flush_log_at_trx_commit</span> <span class="token punctuation">=</span> <span class="token value attr-value">1   # redo 每次提交落盘</span>
<span class="token key attr-name">sync_binlog</span> <span class="token punctuation">=</span> <span class="token value attr-value">1                      # binlog 每次提交刷盘</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_6-高可用与扩展" tabindex="-1"><a class="header-anchor" href="#_6-高可用与扩展" aria-hidden="true">#</a> 6. 高可用与扩展</h2><h3 id="_6-1-主从复制" tabindex="-1"><a class="header-anchor" href="#_6-1-主从复制" aria-hidden="true">#</a> 6.1 主从复制</h3><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> LR
  M<span class="token text string">[&quot;主库&lt;br/&gt;写 binlog&quot;]</span> <span class="token arrow operator">--&gt;</span><span class="token label property">|binlog|</span> D<span class="token text string">[&quot;从库 IO 线程&lt;br/&gt;写 relay log&quot;]</span>
  D <span class="token arrow operator">--&gt;</span> S<span class="token text string">[&quot;从库 SQL 线程&lt;br/&gt;重放&quot;]</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>格式：<strong>ROW</strong>（默认，最安全）、STATEMENT（可能主从不一致）、MIXED</li><li>模式：异步（可能丢尾部数据）→ <strong>半同步</strong>（至少一个从库确认收到 binlog）→ 组复制 MGR（Paxos 多数派）</li><li>延迟治理：并行复制（8.0 基于 WRITESET）、从库只读、大事务拆分</li></ul><h3 id="_6-2-读写分离与分库分表" tabindex="-1"><a class="header-anchor" href="#_6-2-读写分离与分库分表" aria-hidden="true">#</a> 6.2 读写分离与分库分表</h3><ul><li>读写分离注意<strong>复制延迟</strong>：写后立即读走主库（粘性）或用 GTID 等待位点</li><li>垂直拆分（按业务/列）→ 水平拆分（按 shard key 取模/范围/一致性哈希）</li><li>水平拆分的代价：跨分片查询、分布式事务、全局 ID（雪花算法/号段）、扩容数据迁移——<strong>不到数据量瓶颈别拆，先索引/读写分离/归档</strong></li></ul><hr><h2 id="_7-与-postgresql-快速对照" tabindex="-1"><a class="header-anchor" href="#_7-与-postgresql-快速对照" aria-hidden="true">#</a> 7. 与 PostgreSQL 快速对照</h2><table><thead><tr><th>维度</th><th>MySQL (InnoDB)</th><th>PostgreSQL</th></tr></thead><tbody><tr><td>默认隔离级别</td><td>REPEATABLE READ</td><td>READ COMMITTED</td></tr><tr><td>MVCC 实现</td><td>undo log 版本链</td><td>行多版本（xmin/xmax），需 VACUUM</td></tr><tr><td>并发写入高负载</td><td>行锁 + 间隙锁</td><td>读不阻塞写，更接近 OTW</td></tr><tr><td>复杂查询/分析</td><td>弱一些（8.0 有 CTE/窗口/hash join）</td><td>优化器更强，GIS/JSONB/全文更全</td></tr><tr><td>生态定位</td><td>互联网 OLTP 事实标准</td><td>功能型/复杂业务、JSONB 文档混用</td></tr></tbody></table><hr><h2 id="_8-读完马上做" tabindex="-1"><a class="header-anchor" href="#_8-读完马上做" aria-hidden="true">#</a> 8. 读完马上做</h2><ul><li><input type="checkbox" class="task-checkbox" disabled> 对项目里最慢的一条 SQL 跑 explain，说出 type 与 Extra</li><li><input type="checkbox" class="task-checkbox" disabled> 把深分页接口改成游标分页</li><li><input type="checkbox" class="task-checkbox" disabled> 检查生产库 <code>innodb_flush_log_at_trx_commit</code> 与 <code>sync_binlog</code> 取值</li><li><input type="checkbox" class="task-checkbox" disabled> 写一个脚本定期查 <code>information_schema.innodb_trx</code> 里的长事务</li></ul>`,47)),a("blockquote",null,[a("p",null,[t[9]||(t[9]=n("延伸：",-1)),s(e,{to:"/blogs/backend/redis.html"},{default:d(()=>[...t[5]||(t[5]=[n("Redis",-1)])]),_:1}),t[10]||(t[10]=n(" · ",-1)),s(e,{to:"/blogs/backend/mongodb.html"},{default:d(()=>[...t[6]||(t[6]=[n("MongoDB",-1)])]),_:1}),t[11]||(t[11]=n(" · ",-1)),s(e,{to:"/blogs/backend/mq.html"},{default:d(()=>[...t[7]||(t[7]=[n("消息队列",-1)])]),_:1}),t[12]||(t[12]=n(" · ",-1)),s(e,{to:"/blogs/backend/docker.html"},{default:d(()=>[...t[8]||(t[8]=[n("Docker",-1)])]),_:1})])])])}const b=o(p,[["render",u],["__file","mysql.html.vue"]]);export{b as default};
